/// Makes the proposal from the sample, saves it to Documents (CI copies it next to the screenshots) and shows page 1.
struct ProposalPreviewRoute: View {
    let company: Bool
    @State private var image: UIImage?

    var body: some View {
        ScrollView {
            if let image { Image(uiImage: image).resizable().scaledToFit() } else { ProgressView().padding(40) }
        }
        .background(Color.white)
        .onAppear { image = Self.make(company: company) }
    }

    static func make(company: Bool) -> UIImage? {
        guard let data = ScreenshotSamples.proposalJSON.data(using: .utf8),
              let result = try? JSONDecoder().decode(DocEstimateResult.self, from: data) else { return nil }
        var p = ProposalProfile()
        if company {
            p.company = "ООО «СтройМастер Юг»"; p.inn = "2320123456"; p.kpp = "232001001"; p.ogrn = "1222300012345"
            p.address = "354000, г. Сочи, ул. Навагинская, д. 9, оф. 12"; p.phone = "+7 (862) 555-12-34"
            p.email = "info@stroymaster-ug.ru"; p.website = "stroymaster-ug.ru"; p.signerName = "Петров А. В."
            p.bankName = "ПАО «Банк»"; p.account = "40702810900000012345"; p.corrAccount = "30101810400000000999"; p.bik = "040349999"
        }
        var d = ProposalDetails(number: "КП-261125-042")
        d.client = "Иванов Сергей Петрович"; d.address = "г. Сочи, ул. Виноградная, 15"; d.term = "35 рабочих дней"
        guard let url = CommercialProposalPDF.make(result, profile: p, logo: nil, details: d) else { return nil }
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let copy = docs.appendingPathComponent("screenshot-\(company ? "kpco" : "kp").pdf")
        try? FileManager.default.removeItem(at: copy)
        try? FileManager.default.copyItem(at: url, to: copy)
        guard let page = PDFDocument(url: url)?.page(at: 0) else { return nil }
        let b = page.bounds(for: .mediaBox)
        return page.thumbnail(of: CGSize(width: b.width * 2, height: b.height * 2), for: .mediaBox)
    }
}
